import{_ as i,c as a,o as e,aj as t}from"./chunks/framework.BZUl9-wD.js";const k=JSON.parse('{"title":"Installation Guide","description":"Torch-RecHub installation instructions for stable and development versions","frontmatter":{"title":"Installation Guide","description":"Torch-RecHub installation instructions for stable and development versions"},"headers":[],"relativePath":"guide/install.md","filePath":"en/guide/install.md"}'),n={name:"guide/install.md"};function l(h,s,r,o,p,d){return e(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="installation-guide" tabindex="-1">Installation Guide <a class="header-anchor" href="#installation-guide" aria-label="Permalink to “Installation Guide”">​</a></h1><p>This document provides detailed installation instructions for Torch-RecHub, including stable and development versions.</p><h2 id="system-requirements" tabindex="-1">System Requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to “System Requirements”">​</a></h2><ul><li>Python 3.10 or later</li><li>PyTorch <code>&gt;=2.6,&lt;3</code></li></ul><p>NumPy (1.26.4+), pandas (2.1+), and scikit-learn (1.4+) are installed with the package. The optional generative models use Transformers (<code>&gt;=4.57.3,&lt;5</code>).</p><h2 id="installation-methods" tabindex="-1">Installation Methods <a class="header-anchor" href="#installation-methods" aria-label="Permalink to “Installation Methods”">​</a></h2><p>For CPU training, install the stable release or use the source checkout below. For GPU or NPU training, first install the <a href="#install-pytorch-for-your-device">PyTorch build for your device</a>, then install Torch-RecHub in the same environment.</p><h3 id="stable-version" tabindex="-1">Stable Version <a class="header-anchor" href="#stable-version" aria-label="Permalink to “Stable Version”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torch-rechub</span></span></code></pre></div><h3 id="optional-features" tabindex="-1">Optional Features <a class="header-anchor" href="#optional-features" aria-label="Permalink to “Optional Features”">​</a></h3><p>The default installation includes the core training dependencies. Use the pip commands below for the release package. In a source checkout, run <code>uv sync --extra &lt;name&gt;</code>, for example <code>uv sync --extra visualization</code>.</p><table tabindex="0"><thead><tr><th>Use case</th><th>Command</th></tr></thead><tbody><tr><td>Generative models</td><td><code>python -m pip install &quot;torch-rechub[generative]&quot;</code></td></tr><tr><td>Streaming Parquet data</td><td><code>python -m pip install &quot;torch-rechub[bigdata]&quot;</code></td></tr><tr><td>ONNX export and quantization</td><td><code>python -m pip install &quot;torch-rechub[onnx]&quot;</code></td></tr><tr><td>Model visualization</td><td><code>python -m pip install &quot;torch-rechub[visualization]&quot;</code></td></tr><tr><td>Experiment tracking</td><td><code>python -m pip install &quot;torch-rechub[tracking]&quot;</code></td></tr><tr><td>Vector search</td><td><code>python -m pip install &quot;torch-rechub[annoy]&quot;</code> (choose <code>annoy</code>, <code>faiss</code>, or <code>milvus</code> for your backend)</td></tr><tr><td>Testing, formatting, and type checking</td><td><code>python -m pip install &quot;torch-rechub[dev]&quot;</code></td></tr><tr><td>All optional features</td><td><code>python -m pip install &quot;torch-rechub[all]&quot;</code></td></tr></tbody></table><p>Rendering model graphs also requires the Graphviz <code>dot</code> executable on your system path.</p><p>You can run a script with an extra using <code>uv run --extra &lt;name&gt; python &lt;script.py&gt;</code>. Repeat <code>--extra</code> if the script needs several extras.</p><h3 id="latest-development-version" tabindex="-1">Latest Development Version <a class="header-anchor" href="#latest-development-version" aria-label="Permalink to “Latest Development Version”">​</a></h3><p>To install the development version with the latest features:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install uv first (if not already installed)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uv</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Clone and install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/datawhalechina/torch-rechub.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torch-rechub</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Create .venv, install locked dependencies, and install this project editable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span></span></code></pre></div><p>If you have already installed a device-specific PyTorch build, use <code>uv pip install -e .</code> for the last step and run examples with the <code>python</code> from that activated environment.</p><h2 id="development-environment-setup" tabindex="-1">Development Environment Setup <a class="header-anchor" href="#development-environment-setup" aria-label="Permalink to “Development Environment Setup”">​</a></h2><p>If you want to contribute to Torch-RecHub or work with the source code:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Fork and clone the repository</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/YOUR_USERNAME/torch-rechub.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torch-rechub</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Install dependencies and set up environment</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Run tests (uv sync already installs this project editable)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span></span></code></pre></div><h2 id="install-pytorch-for-your-device" tabindex="-1">Install PyTorch for Your Device <a class="header-anchor" href="#install-pytorch-for-your-device" aria-label="Permalink to “Install PyTorch for Your Device”">​</a></h2><p>For NVIDIA GPUs, choose a CUDA build supported by your GPU and driver. For AMD GPUs, choose a ROCm build for your GPU architecture. For Huawei Ascend NPUs, install and load CANN, then select compatible versions of PyTorch and <code>torch-npu</code>. Check the <a href="https://pytorch.org/get-started/locally/" target="_blank" rel="noreferrer">PyTorch selector</a>, <a href="https://rocm.docs.amd.com/projects/radeon-ryzen/en/latest/" target="_blank" rel="noreferrer">AMD ROCm documentation</a>, or <a href="https://github.com/Ascend/pytorch/blob/master/COMPATIBILITY.md" target="_blank" rel="noreferrer">Ascend compatibility table</a> for your configuration.</p><p>Activate your Python environment and choose one command for your device. With uv, you can use <code>uv pip</code> in place of <code>python -m pip</code>.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># CPU-only build on Linux or Windows</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --index-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://download.pytorch.org/whl/cpu</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># NVIDIA GPU, for example with CUDA 12.6</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --index-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://download.pytorch.org/whl/cu126</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># AMD GPU, for example a Ryzen AI Max+ 395 (gfx1151)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --index-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://repo.amd.com/rocm/whl/gfx1151/</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;rocm[libraries,devel]&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torchvision</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torchaudio</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Huawei Ascend NPU, when the default packages match your CANN version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torch-npu</span></span></code></pre></div><p>To train on the first device, set <code>device=&quot;cuda:0&quot;</code> in the trainer for NVIDIA or AMD. For Ascend, import <code>torch_npu</code> and set <code>device=&quot;npu:0&quot;</code>.</p><h2 id="verify-installation" tabindex="-1">Verify Installation <a class="header-anchor" href="#verify-installation" aria-label="Permalink to “Verify Installation”">​</a></h2><p>Check the version in the environment where you installed Torch-RecHub.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import torch_rechub; print(torch_rechub.__version__)&quot;</span></span></code></pre></div><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><h3 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to “Common Issues”">​</a></h3><p>If you encounter any installation issues:</p><ol><li>Check <a href="https://github.com/datawhalechina/torch-rechub/issues" target="_blank" rel="noreferrer">GitHub Issues</a></li><li>Create a new Issue with detailed error messages and system information</li><li>Refer to the <a href="/torch-rechub/community/faq.html">FAQ</a></li></ol>`,33)])])}const u=i(n,[["render",l]]);export{k as __pageData,u as default};
